"""Construct image-free reports from explicitly selected scientific fields"""

import json
import zipfile
from pathlib import Path
from tinysr.common.io import sha256


def public_report(data):
    """Never export free text, local environment dumps, paths, or image fingerprints"""
    pairs = []
    for p in data.get("pairs", []):
        # use only the documented names generated by the baseline evaluator
        allowed = {
            "C16",
            "C24",
            "C32",
            "bicubic",
            "native_bilinear_display",
            "saved_device_C16",
        }
        if p.get("first") not in allowed or p.get("second") not in allowed:
            continue
        pairs.append(
            {
                k: p[k]
                for k in (
                    "first",
                    "second",
                    "first_wins",
                    "ties",
                    "second_wins",
                    "ratings",
                    "reviewed_scenes",
                    "scene_mean_first_win_rate",
                    "scene_mean_tie_rate",
                    "scene_mean_second_win_rate",
                    "artifacts",
                )
                if k in p
            }
        )
    return {
        "schema": "tinysr.public_metrics.v1",
        "scene_count": int(data.get("scene_count", 0)),
        "review_complete": data.get("status") == "complete",
        "pending_rows": int(data.get("pending_rows", 0)),
        "pairs": pairs,
        "camera_hr_ground_truth": False,
    }


def export_metrics(folder, destination):
    """Export reviewed aggregates only and never glob an experiment directory"""
    folder, destination = Path(folder), Path(destination)
    if destination.exists():
        raise FileExistsError("Preserve previous exports")
    source = folder / "review_summary.json"
    if not source.is_file():
        raise ValueError("Summarize review before exporting metrics")
    data = public_report(json.loads(source.read_text()))
    destination.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(destination, "x", zipfile.ZIP_DEFLATED) as archive:
        archive.writestr("metrics.json", json.dumps(data, indent=2, allow_nan=False))
    return destination
